import { open } from 'node:fs/promises';
import path from 'node:path';
import { createCodexAdapter } from '../agents/codex.js';
import { createClaudeAdapter } from '../agents/claude.js';
import type { CodingAgentResult } from '../agents/types.js';
import {
  FORCE_KILL_GRACE_MS,
  MAX_PROCESS_OUTPUT_BYTES,
  ProcessExecutionError,
  runProcess,
  validateProcessResult,
  type ProcessRequest,
  type ProcessResult,
  type ProcessRunner,
} from '../process.js';
import { resolveSafeRepoFile, type CandidateProposal } from './candidate.js';
import { isAllowedDiagnosticCommand } from './diagnostics.js';

export {
  FORCE_KILL_GRACE_MS,
  runProcess,
  type ProcessRequest,
  type ProcessResult,
  type ProcessRunner,
};
export const MAX_TOOL_OUTPUT_BYTES = MAX_PROCESS_OUTPUT_BYTES;
export const MAX_SEARCH_RESULTS = 50;
export const MAX_READ_FILE_BYTES = 64 * 1024;
export const SEARCH_TIMEOUT_MS = 10_000;
export const DIAGNOSTIC_TIMEOUT_MS = 10_000;
export const VALIDATION_TIMEOUT_MS = 120_000;

export type ToolResult = {
  action: CandidateProposal['action'];
  ok: boolean;
  exitCode: number | null;
  durationMs: number;
  timedOut: boolean;
  output: string;
  files: string[];
  stdout?: string;
  stderr?: string;
};

export class ToolExecutionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ToolExecutionError';
  }
}

function normalizedOutput(result: ProcessResult): string {
  const combined = [result.stdout.trim(), result.stderr.trim()].filter(Boolean).join('\n');
  return combined || (result.timedOut ? 'Process timed out.' : 'Process produced no output.');
}

function normalizedAgentOutput(result: ProcessResult): string {
  const finalMessage = result.stdout.trim();
  if (finalMessage) return finalMessage;
  const diagnostics = result.stderr.trim();
  return diagnostics || (result.timedOut ? 'Process timed out.' : 'Process produced no output.');
}

function codingAgentToolResult(
  action: 'CALL_CODEX' | 'CALL_CLAUDE',
  result: CodingAgentResult,
): ToolResult {
  return {
    action,
    ok: result.ok,
    exitCode: result.exitCode,
    durationMs: result.durationMs,
    timedOut: result.timedOut,
    output: normalizedAgentOutput(result),
    files: [],
    stdout: result.stdout,
    stderr: result.stderr,
  };
}

function searchArgs(terms: string[]): string[] {
  const patterns = terms.flatMap((term) => ['-e', term]);
  return [
    '--files-with-matches',
    '--fixed-strings',
    '--ignore-case',
    '--hidden',
    '--glob',
    '!.git/**',
    '--glob',
    '!node_modules/**',
    '--glob',
    '!dist/**',
    '--glob',
    '!traces/**',
    '--glob',
    '!**/.env',
    '--glob',
    '!**/.env.*',
    '--glob',
    '!**/credentials*',
    '--glob',
    '!**/secrets*',
    '--glob',
    '!**/*.pem',
    '--glob',
    '!**/*.key',
    ...patterns,
    '.',
  ];
}

function normalizeSearchFiles(stdout: string): string[] {
  return stdout
    .split(/\r?\n/u)
    .map((entry) => entry.replace(/^\.\//u, '').trim())
    .filter(Boolean)
    .filter((entry, index, values) => values.indexOf(entry) === index)
    .sort()
    .slice(0, MAX_SEARCH_RESULTS);
}

async function executeRead(proposal: Extract<CandidateProposal, { action: 'READ_FILE' }>): Promise<ToolResult> {
  const startedAt = performance.now();
  const safeRelativePath = await resolveSafeRepoFile(proposal.input.root, proposal.input.path);
  const filePath = path.join(proposal.input.root, safeRelativePath);
  const file = await open(filePath, 'r');
  try {
    const contents = Buffer.alloc(MAX_READ_FILE_BYTES + 1);
    const { bytesRead } = await file.read(contents, 0, contents.length, 0);
    if (bytesRead > MAX_READ_FILE_BYTES) {
      return {
        action: proposal.action,
        ok: false,
        exitCode: null,
        durationMs: Math.round(performance.now() - startedAt),
        timedOut: false,
        output: `File exceeds the ${MAX_READ_FILE_BYTES}-byte read limit.`,
        files: [],
      };
    }
    return {
      action: proposal.action,
      ok: true,
      exitCode: 0,
      durationMs: Math.round(performance.now() - startedAt),
      timedOut: false,
      output: contents.subarray(0, bytesRead).toString('utf8'),
      files: [safeRelativePath],
    };
  } finally {
    await file.close();
  }
}

export async function executeCandidate(
  proposal: CandidateProposal,
  runner: ProcessRunner = runProcess,
): Promise<ToolResult> {
  if (proposal.action === 'ASK_USER' || proposal.action === 'FINISH') {
    throw new ToolExecutionError(`${proposal.action} does not execute a repository tool.`);
  }
  if (proposal.action === 'READ_FILE') return executeRead(proposal);
  if (proposal.action === 'CALL_CODEX') {
    const result = await createCodexAdapter(runner)({
      root: proposal.input.root,
      task: proposal.input.task,
      context: proposal.input.context,
    });
    return codingAgentToolResult(proposal.action, result);
  }
  if (proposal.action === 'CALL_CLAUDE') {
    const result = await createClaudeAdapter(runner)({
      root: proposal.input.root,
      task: proposal.input.task,
      context: proposal.input.context,
    });
    return codingAgentToolResult(proposal.action, result);
  }

  if (proposal.action === 'RUN_TESTS') {
    const expectedCommand = proposal.input.packageManager;
    const expectedArgs = ['run', proposal.input.script];
    if (
      proposal.input.command !== expectedCommand ||
      proposal.input.args.length !== expectedArgs.length ||
      proposal.input.args.some((arg, index) => arg !== expectedArgs[index])
    ) {
      throw new ToolExecutionError('The validation proposal does not match its package-manager script.');
    }
  }
  if (
    proposal.action === 'RUN_COMMAND' &&
    !isAllowedDiagnosticCommand(
      proposal.input.diagnostic,
      proposal.input.command,
      proposal.input.args,
    )
  ) {
    throw new ToolExecutionError('The diagnostic proposal does not match the fixed command allowlist.');
  }

  const startedAt = performance.now();
  let request: ProcessRequest;
  if (proposal.action === 'SEARCH_REPO') {
    request = {
      command: 'rg',
      args: searchArgs(proposal.input.terms),
      cwd: proposal.input.root,
      timeoutMs: SEARCH_TIMEOUT_MS,
    };
  } else if (proposal.action === 'RUN_COMMAND') {
    request = {
      command: proposal.input.command,
      args: proposal.input.args,
      cwd: proposal.input.root,
      timeoutMs: DIAGNOSTIC_TIMEOUT_MS,
    };
  } else {
    request = {
      command: proposal.input.command,
      args: proposal.input.args,
      cwd: proposal.input.root,
      timeoutMs: VALIDATION_TIMEOUT_MS,
    };
  }
  const result = await runner(request);
  try {
    validateProcessResult(result);
  } catch (error) {
    if (error instanceof ProcessExecutionError) {
      throw new ToolExecutionError(error.message);
    }
    throw error;
  }
  const files = proposal.action === 'SEARCH_REPO'
    ? normalizeSearchFiles(result.stdout)
    : [];
  const successfulSearch = proposal.action === 'SEARCH_REPO' && result.exitCode === 1;

  return {
    action: proposal.action,
    ok: !result.timedOut && (result.exitCode === 0 || successfulSearch),
    exitCode: result.exitCode,
    durationMs: Math.round(performance.now() - startedAt),
    timedOut: result.timedOut,
    output: normalizedOutput(result),
    files,
  };
}
import { randomUUID } from 'node:crypto';
import { appendFile, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { AgentState, EvaluationResult, PolicyDecision } from '../types.js';

export const TRACE_SCHEMA_VERSION = 1;
export const ORCHESTRATION_TRACE_SCHEMA_VERSION = 2;
export const MAX_TRACE_VALUE_BYTES = 8 * 1024;

const MAX_TRACE_DEPTH = 6;
const MAX_TRACE_ARRAY_ITEMS = 32;
const MAX_TRACE_OBJECT_ENTRIES = 32;
const MAX_TRACE_STRING_LENGTH = 1_024;
const MAX_TRACE_TEXT_BUDGET = 6_000;
const MAX_TRACE_WRITE_ATTEMPTS = 3;
const REDACTED = '[REDACTED]';
const TRUNCATED = '[TRUNCATED]';
const SENSITIVE_KEY = /api[-_ ]?key|authorization|token|secret|password|credential|cookie|session/i;
const KEY_VALUE_SECRET = /((?:api[-_ ]?key|authorization|token|secret|password|credential|cookie|session)\s*[:=]\s*)(?:(?:Bearer\s+)[^\s,;\\]+|"[^"]*"|'[^']*'|[^\s,;\\]+)/gi;
const BEARER_TOKEN = /(\bBearer\s+)[A-Za-z0-9._~+/=-]+/gi;

export type TraceValue =
  | null
  | boolean
  | number
  | string
  | TraceValue[]
  | { [key: string]: TraceValue };

export type TraceRecord = {
  schemaVersion: typeof TRACE_SCHEMA_VERSION;
  runId: string;
  timestamp: string;
  state: TraceValue;
  evaluation: {
    assessment: TraceValue;
    model: string;
    latencyMs: number;
    rawAnswers: TraceValue;
  };
  policy: TraceValue;
};

export type OrchestrationTracePayload = {
  iteration: number;
  stateBefore: AgentState;
  evaluation: EvaluationResult;
  policy: PolicyDecision;
  proposal: unknown;
  approval: unknown;
  toolInput: unknown;
  toolResult: unknown;
  stateAfter: AgentState;
  workerRequest?: unknown;
};

export class TraceWriteError extends Error {
  constructor() {
    super('Unable to write the decision trace. Re-run with --no-trace only when an unrecorded decision is acceptable.');
    this.name = 'TraceWriteError';
  }
}

type SanitizationContext = {
  remainingText: number;
  seen: WeakSet<object>;
  secretValues: string[];
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function configuredSecretValues(): string[] {
  const gatewayKey = process.env.AI_GATEWAY_API_KEY?.trim();
  return gatewayKey ? [gatewayKey] : [];
}

export function redactSensitiveText(
  value: string,
  secretValues: string[] = configuredSecretValues(),
): string {
  let redacted = value;
  for (const secret of secretValues) {
    redacted = redacted.replaceAll(secret, REDACTED);
  }
  return redacted
    .replace(KEY_VALUE_SECRET, `$1${REDACTED}`)
    .replace(BEARER_TOKEN, `$1${REDACTED}`);
}

function takeText(value: string, context: SanitizationContext): string {
  const redacted = redactSensitiveText(value, context.secretValues);
  const available = Math.min(MAX_TRACE_STRING_LENGTH, context.remainingText);
  if (available <= 0) return TRUNCATED;
  context.remainingText -= Math.min(redacted.length, available);
  return redacted.length > available ? `${redacted.slice(0, available)}${TRUNCATED}` : redacted;
}

function sanitizeValue(value: unknown, context: SanitizationContext, depth: number): TraceValue {
  if (depth > MAX_TRACE_DEPTH) return TRUNCATED;
  if (value === undefined) return '[UNDEFINED]';
  if (value === null || typeof value === 'boolean') return value;
  if (typeof value === 'number') return Number.isFinite(value) ? value : String(value);
  if (typeof value === 'string') return takeText(value, context);
  if (typeof value === 'bigint' || typeof value === 'symbol' || typeof value === 'function') {
    return takeText(String(value), context);
  }

  if (context.seen.has(value)) return '[CIRCULAR]';
  context.seen.add(value);

  if (Array.isArray(value)) {
    const items = value.slice(0, MAX_TRACE_ARRAY_ITEMS)
      .map((item) => sanitizeValue(item, context, depth + 1));
    if (value.length > MAX_TRACE_ARRAY_ITEMS) items.push(TRUNCATED);
    return items;
  }

  if (!isRecord(value)) return takeText(String(value), context);

  const entries: { [key: string]: TraceValue } = {};
  const objectEntries = Object.entries(value).slice(0, MAX_TRACE_OBJECT_ENTRIES);
  for (const [key, entry] of objectEntries) {
    entries[key] = SENSITIVE_KEY.test(key)
      ? REDACTED
      : sanitizeValue(entry, context, depth + 1);
  }
  if (Object.keys(value).length > MAX_TRACE_OBJECT_ENTRIES) entries.truncated = TRUNCATED;
  return entries;
}

export function sanitizeTraceValue(
  value: unknown,
  secretValues: string[] = configuredSecretValues(),
): TraceValue {
  const sanitized = sanitizeValue(value, {
    remainingText: MAX_TRACE_TEXT_BUDGET,
    seen: new WeakSet<object>(),
    secretValues,
  }, 0);
  const serialized = JSON.stringify(sanitized);
  if (Buffer.byteLength(serialized, 'utf8') <= MAX_TRACE_VALUE_BYTES) return sanitized;

  return {
    truncated: true,
    preview: takeText(serialized, {
      remainingText: Math.floor(MAX_TRACE_VALUE_BYTES / 4),
      seen: new WeakSet<object>(),
      secretValues,
    }),
  };
}

function makeTraceRecord(
  payload: {
    state: AgentState;
    evaluation: EvaluationResult;
    policy: PolicyDecision;
  },
  date: Date,
  runId: string,
): TraceRecord {
  const secretValues = configuredSecretValues();
  return {
    schemaVersion: TRACE_SCHEMA_VERSION,
    runId,
    timestamp: date.toISOString(),
    state: sanitizeTraceValue(payload.state, secretValues),
    evaluation: {
      assessment: sanitizeTraceValue(payload.evaluation.assessment, secretValues),
      model: redactSensitiveText(payload.evaluation.model, secretValues),
      latencyMs: Number.isFinite(payload.evaluation.latencyMs) ? payload.evaluation.latencyMs : 0,
      rawAnswers: sanitizeTraceValue(payload.evaluation.rawAnswers, secretValues),
    },
    policy: sanitizeTraceValue(payload.policy, secretValues),
  };
}

function isFileExistsError(error: unknown): boolean {
  return isRecord(error) && error.code === 'EEXIST';
}

async function uniqueTracePath(root: string): Promise<{ path: string; runId: string }> {
  const traceDir = path.join(root, 'traces');
  await mkdir(traceDir, { recursive: true });

  for (let attempt = 0; attempt < MAX_TRACE_WRITE_ATTEMPTS; attempt += 1) {
    const date = new Date();
    const runId = `${date.toISOString().replaceAll(':', '-').replaceAll('.', '-')}-${randomUUID()}`;
    const tracePath = path.join(traceDir, `${runId}.jsonl`);
    try {
      await writeFile(tracePath, '', { flag: 'wx' });
      return { path: tracePath, runId };
    } catch (error) {
      if (isFileExistsError(error)) continue;
      throw error;
    }
  }

  throw new Error('Unable to allocate a unique trace path.');
}

export async function writeTrace(
  root: string,
  payload: {
    state: AgentState;
    evaluation: EvaluationResult;
    policy: PolicyDecision;
  },
): Promise<string> {
  try {
    const trace = await uniqueTracePath(root);
    const record = makeTraceRecord(payload, new Date(), trace.runId);
    await writeFile(trace.path, `${JSON.stringify(record)}\n`);
    return trace.path;
  } catch {
    throw new TraceWriteError();
  }
}

export async function createOrchestrationTrace(root: string): Promise<{
  path: string;
  runId: string;
}> {
  try {
    return await uniqueTracePath(root);
  } catch {
    throw new TraceWriteError();
  }
}

export async function appendOrchestrationTrace(
  trace: { path: string; runId: string },
  payload: OrchestrationTracePayload,
): Promise<void> {
  const secretValues = configuredSecretValues();
  const record = {
    schemaVersion: ORCHESTRATION_TRACE_SCHEMA_VERSION,
    runId: trace.runId,
    timestamp: new Date().toISOString(),
    iteration: payload.iteration,
    stateBefore: sanitizeTraceValue(payload.stateBefore, secretValues),
    evaluation: {
      assessment: sanitizeTraceValue(payload.evaluation.assessment, secretValues),
      model: redactSensitiveText(payload.evaluation.model, secretValues),
      latencyMs: Number.isFinite(payload.evaluation.latencyMs) ? payload.evaluation.latencyMs : 0,
      rawAnswers: sanitizeTraceValue(payload.evaluation.rawAnswers, secretValues),
    },
    policy: sanitizeTraceValue(payload.policy, secretValues),
    proposal: sanitizeTraceValue(payload.proposal, secretValues),
    approval: sanitizeTraceValue(payload.approval, secretValues),
    toolInput: sanitizeTraceValue(payload.toolInput, secretValues),
    toolResult: sanitizeTraceValue(payload.toolResult, secretValues),
    ...(payload.workerRequest === undefined
      ? {}
      : { workerRequest: sanitizeTraceValue(payload.workerRequest, secretValues) }),
    stateAfter: sanitizeTraceValue(payload.stateAfter, secretValues),
  };

  try {
    await appendFile(trace.path, `${JSON.stringify(record)}\n`);
  } catch {
    throw new TraceWriteError();
  }
}
import {
  APICallError,
  experimental_evaluate as evaluate,
  InvalidResponseDataError,
  NoSuchModelError,
  RetryError,
  type Experimental_EvaluationModel as EvaluationModel,
} from 'ai';
import type { Action, AgentAssessment, AgentState, EvaluationResult } from '../types.js';
import {
  limitStrings,
  MAX_EVALUATION_COMMAND_OUTPUT_LENGTH,
  MAX_EVALUATION_COMMANDS,
  MAX_EVALUATION_LIST_ITEMS,
  MAX_EVALUATION_TEXT_LENGTH,
  MAX_TASK_LENGTH,
  truncateText,
} from '../limits.js';

export const JEV_EVALUATION_TIMEOUT_MS = 10_000;
export const JEV_EVALUATION_MAX_RETRIES = 1;

export type JevEvaluationErrorCode =
  | 'timeout'
  | 'authentication'
  | 'rate_limit'
  | 'model_unavailable'
  | 'invalid_response'
  | 'service_unavailable'
  | 'request_failed';

export class JevEvaluationError extends Error {
  readonly code: JevEvaluationErrorCode;

  constructor(code: JevEvaluationErrorCode, message: string) {
    super(message);
    this.name = 'JevEvaluationError';
    this.code = code;
  }
}

const ACTION_CRITERIA = {
  SEARCH_REPO: 'Search repository contents to locate relevant code or configuration.',
  READ_FILE: 'Inspect one or more known files before deciding what to change.',
  RUN_COMMAND: 'Run a safe, non-destructive diagnostic command.',
  RUN_TESTS: 'Run an existing test, typecheck, lint, or build validation script.',
  CALL_CODEX: 'Delegate implementation or deeper coding analysis to Codex.',
  CALL_CLAUDE: 'Delegate implementation or deeper coding analysis to Claude Code.',
  ASK_USER: 'Required information or authorization is unavailable and must come from the user.',
  FINISH: 'The requested task is complete and adequately validated.',
} as const;

export function boundAgentStateForEvaluation(state: AgentState): AgentState {
  const { repo, evidence: _evidence, ...boundedState } = state;
  return {
    ...boundedState,
    task: truncateText(state.task, MAX_TASK_LENGTH),
    currentGoal: truncateText(state.currentGoal, MAX_EVALUATION_TEXT_LENGTH),
    repo: {
      root: truncateText(repo.root, MAX_EVALUATION_TEXT_LENGTH),
      packageManager: repo.packageManager,
      ...(repo.packageName
        ? { packageName: truncateText(repo.packageName, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
      scripts: limitStrings(repo.scripts),
      validationScripts: limitStrings(repo.validationScripts),
      ...(repo.gitBranch
        ? { gitBranch: truncateText(repo.gitBranch, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
      gitStatus: limitStrings(repo.gitStatus),
      topLevelFiles: limitStrings(repo.topLevelFiles),
    },
    filesRead: limitStrings(state.filesRead),
    filesModified: limitStrings(state.filesModified),
    observations: limitStrings(state.observations),
    commandsRun: state.commandsRun.slice(0, MAX_EVALUATION_COMMANDS).map((command) => ({
      command: truncateText(command.command, MAX_EVALUATION_TEXT_LENGTH),
      exitCode: command.exitCode,
      output: truncateText(command.output, MAX_EVALUATION_COMMAND_OUTPUT_LENGTH),
    })),
    tests: {
      ran: state.tests.ran,
      ...(state.tests.passed !== undefined ? { passed: state.tests.passed } : {}),
      ...(state.tests.summary !== undefined
        ? { summary: truncateText(state.tests.summary, MAX_EVALUATION_TEXT_LENGTH) }
        : {}),
    },
    failedApproaches: limitStrings(state.failedApproaches, MAX_EVALUATION_LIST_ITEMS),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function isProbability(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
}

function invalidProviderMetadata(): never {
  throw new JevEvaluationError(
    'invalid_response',
    'Jev returned invalid provider metadata.',
  );
}

function getNextActionConfidence(providerMetadata: unknown): number | undefined {
  if (providerMetadata === undefined) return undefined;
  if (!isRecord(providerMetadata)) invalidProviderMetadata();

  const typesafe = providerMetadata.typesafe;
  if (typesafe === undefined) return undefined;
  if (!isRecord(typesafe)) invalidProviderMetadata();

  const confidence = typesafe.confidence;
  if (confidence === undefined) return undefined;
  if (!isRecord(confidence)) invalidProviderMetadata();

  const nextAction = confidence.nextAction;
  if (nextAction === undefined) return undefined;
  if (!isProbability(nextAction)) invalidProviderMetadata();

  return nextAction;
}

function isTimeoutError(error: unknown): boolean {
  return (
    (RetryError.isInstance(error) && error.reason === 'abort') ||
    (error instanceof Error && (error.name === 'AbortError' || error.name === 'TimeoutError'))
  );
}

function lastEvaluationError(error: unknown): unknown {
  return RetryError.isInstance(error) ? error.lastError : error;
}

function getStatusCode(error: unknown): number | undefined {
  if (APICallError.isInstance(error)) return error.statusCode;
  if (!isRecord(error)) return undefined;
  const statusCode = error.statusCode;
  return typeof statusCode === 'number' && Number.isInteger(statusCode)
    ? statusCode
    : undefined;
}

export function normalizeJevEvaluationError(error: unknown): JevEvaluationError {
  if (error instanceof JevEvaluationError) return error;
  if (isTimeoutError(error)) {
    return new JevEvaluationError(
      'timeout',
      `Jev evaluation timed out after ${JEV_EVALUATION_TIMEOUT_MS / 1000} seconds.`,
    );
  }

  const lastError = lastEvaluationError(error);
  if (InvalidResponseDataError.isInstance(lastError)) {
    return new JevEvaluationError('invalid_response', 'Jev returned invalid evaluation data.');
  }
  if (NoSuchModelError.isInstance(lastError)) {
    return new JevEvaluationError(
      'model_unavailable',
      'The configured Jev model is unavailable. Check ROUTER_MODEL and Gateway access.',
    );
  }

  switch (getStatusCode(lastError)) {
    case 401:
    case 403:
      return new JevEvaluationError(
        'authentication',
        'Jev Gateway authentication or authorization failed. Check AI_GATEWAY_API_KEY and Gateway access.',
      );
    case 404:
      return new JevEvaluationError(
        'model_unavailable',
        'The configured Jev model is unavailable. Check ROUTER_MODEL and Gateway access.',
      );
    case 429:
      return new JevEvaluationError(
        'rate_limit',
        'Jev Gateway rate limit reached. Wait before retrying the evaluation.',
      );
    default: {
      const statusCode = getStatusCode(lastError);
      if (statusCode !== undefined && statusCode >= 500) {
        return new JevEvaluationError(
          'service_unavailable',
          'Jev Gateway is temporarily unavailable. Try the evaluation again later.',
        );
      }
      return new JevEvaluationError(
        'request_failed',
        'Jev evaluation failed. Try the evaluation again later.',
      );
    }
  }
}

export async function evaluateAgentState(
  state: AgentState,
  model: EvaluationModel = process.env.ROUTER_MODEL ?? 'typesafe-ai/jev',
): Promise<EvaluationResult> {
  const startedAt = performance.now();
  const evaluation = evaluate({
    model,
    state: boundAgentStateForEvaluation(state),
    questions: {
      taskComplete: {
        type: 'boolean',
        instructions: 'Has the original requested coding task been completed and validated?',
        criteria: {
          true: 'The requested outcome exists and available validation supports completion.',
          false: 'Work, evidence, or validation is still missing.',
        },
      },
      needsMoreInformation: {
        type: 'boolean',
        instructions: 'Is information required that cannot be obtained from the repository or safe local inspection?',
      },
      needsTesting: {
        type: 'boolean',
        instructions: 'Should the current implementation or hypothesis be validated now?',
      },
      stuck: {
        type: 'boolean',
        instructions: 'Is the workflow repeating failed approaches or failing to make meaningful progress?',
      },
      nextAction: {
        type: 'choice',
        instructions: 'Which single action would most effectively and safely advance the coding task?',
        criteria: ACTION_CRITERIA,
      },
    },
    maxRetries: JEV_EVALUATION_MAX_RETRIES,
    abortSignal: AbortSignal.timeout(JEV_EVALUATION_TIMEOUT_MS),
    providerOptions: {
      gateway: {
        zeroDataRetention: false,
      },
    },
  });
  let result: Awaited<typeof evaluation>;

  try {
    result = await evaluation;
  } catch (error) {
    throw normalizeJevEvaluationError(error);
  }

  const confidence = getNextActionConfidence(result.providerMetadata);
  const { taskComplete, needsMoreInformation, needsTesting, stuck, nextAction } = result.answers;

  const assessment: AgentAssessment = {
    taskComplete: { probability: taskComplete.probability },
    needsMoreInformation: { probability: needsMoreInformation.probability },
    needsTesting: { probability: needsTesting.probability },
    stuck: { probability: stuck.probability },
    nextAction: {
      choice: nextAction.choice as Action,
      probabilities: nextAction.probabilities ?? {},
      ...(confidence !== undefined ? { confidence } : {}),
    },
  };

  return {
    assessment,
    model: typeof model === 'string' ? model : process.env.ROUTER_MODEL ?? 'evaluation-model',
    latencyMs: Math.round(performance.now() - startedAt),
    ...(result.providerMetadata ? { providerMetadata: result.providerMetadata } : {}),
    rawAnswers: result.answers,
  };
}

